      material: INTRO_13 + ' ' + PERG_C13 + '\n\n' + MSGS_C + '\n\n' + SINAIS,
      counts: ['Mensagens com o sinal certo (de 6)', 'Vereditos', 'Frases atribuídas a tribunal que o texto colado não traz'],
